import type { ProxyDetail } from './types';
import { tryParseParamObject } from './components/ParamEditor/paramUtils';
import { resolveProxyPrivacy } from './proxyInfo';

export type ClashProxy = Record<string, string | number | boolean> & { name: string; type: string };

export interface ClashVergeExportResult {
  code: string;
  publicCount: number;
  personalCount: number;
  skippedCount: number;
}

const cleanName = (value: string) => value.trim().replace(/[\r\n]/g, ' ');

function buildProxyName(item: ProxyDetail, protocol: string, server: string) {
  const label = cleanName(item.remark || item.proxy_info || '');
  if (label) return label;
  return `${protocol.toUpperCase()}_${server}_${item.id}`;
}

function fromParam(item: ProxyDetail): ClashProxy | null {
  const param = tryParseParamObject(item.param || '{}');
  const clash = param?.clash;
  if (!clash || typeof clash !== 'object' || Array.isArray(clash)) return null;
  const record = clash as Record<string, unknown>;
  const type = String(record.type ?? '').trim();
  const server = String(record.server ?? '').trim();
  const port = Number(record.port);
  if (!type || !server || !Number.isInteger(port) || port <= 0) return null;
  const proxy = { ...record, name: cleanName(String(record.name ?? '')) || buildProxyName(item, type, server), type, server, port };
  return proxy as ClashProxy;
}

function fromURI(item: ProxyDetail): ClashProxy | null {
  const raw = item.proxy_value.trim();
  if (!raw) return null;
  try {
    const url = new URL(raw);
    const scheme = url.protocol.replace(':', '').toLowerCase();
    const type = scheme === 'https' ? 'http' : scheme === 'socks' ? 'socks5' : scheme;
    if (!['http', 'socks4', 'socks5'].includes(type)) return null;
    const port = Number(url.port || (scheme === 'https' ? 443 : 80));
    if (!url.hostname || !Number.isInteger(port) || port <= 0) return null;
    return {
      name: buildProxyName(item, type, url.hostname),
      type,
      server: url.hostname,
      port,
      ...(url.username ? { username: decodeURIComponent(url.username) } : {}),
      ...(url.password ? { password: decodeURIComponent(url.password) } : {}),
      ...(scheme === 'https' ? { tls: true } : {}),
    };
  } catch {
    const match = raw.match(/^([^:\s]+):(\d+):([^:]+):(.+)$/);
    if (!match) return null;
    const [, server, port, username, password] = match;
    return { name: buildProxyName(item, 'http', server), type: 'http', server, port: Number(port), username, password };
  }
}

export function proxyDetailToClash(item: ProxyDetail): ClashProxy | null {
  return fromParam(item) ?? fromURI(item);
}

const scriptTemplate = (publicProxies: ClashProxy[], personalProxies: ClashProxy[]) => `// Generated by CPA Management Center.
function main(config, profileName) {
  const subscriptionProxies = Array.isArray(config.proxies) ? config.proxies : [];
  const publicProxies = ${JSON.stringify(publicProxies, null, 2)};
  const personalProxies = ${JSON.stringify(personalProxies, null, 2)};
  const byName = new Map();
  for (const proxy of [...subscriptionProxies, ...publicProxies, ...personalProxies]) {
    if (proxy && proxy.name && !byName.has(proxy.name)) byName.set(proxy.name, proxy);
  }
  const badNames = new Set([...byName.values()].filter((proxy) => {
    if (proxy?.type !== "hysteria" && proxy?.type !== "hysteria2") return false;
    return String(proxy.up ?? "").trim() === "" || String(proxy.down ?? "").trim() === "";
  }).map((proxy) => proxy.name));
  config.proxies = [...byName.values()].filter((proxy) => !badNames.has(proxy.name));
  const availableNames = new Set(config.proxies.map((proxy) => proxy.name));
  const uniqueNames = (names) => [...new Set(names)].filter((name) => availableNames.has(name));
  const personalNames = uniqueNames(personalProxies.map((proxy) => proxy.name));
  const publicNames = uniqueNames([...subscriptionProxies, ...publicProxies].map((proxy) => proxy.name));
  const allNames = uniqueNames([...personalNames, ...publicNames]);
  if (!Array.isArray(config["proxy-groups"])) config["proxy-groups"] = [];
  const upsertGroup = (group) => {
    const index = config["proxy-groups"].findIndex((item) => item.name === group.name);
    if (index >= 0) config["proxy-groups"][index] = { ...config["proxy-groups"][index], ...group };
    else config["proxy-groups"].unshift(group);
  };
  upsertGroup({ name: "🌍 公开节点", type: "select", proxies: publicNames.length ? publicNames : ["DIRECT"] });
  upsertGroup({ name: "🔒 个人节点", type: "select", proxies: personalNames.length ? personalNames : ["DIRECT"] });
  upsertGroup({ name: "⚡ 自动选择(全)", type: "url-test", url: "https://cp.cloudflare.com/generate_204", interval: 300, tolerance: 150, proxies: allNames.length ? allNames : ["DIRECT"] });
  for (const group of config["proxy-groups"]) {
    if (!Array.isArray(group.proxies)) continue;
    const cleaned = group.proxies.filter((name) => !badNames.has(name));
    group.proxies = group.name === "🚀 节点选择"
      ? [...new Set(["⚡ 自动选择(全)", "🔒 个人节点", "🌍 公开节点", ...cleaned])]
      : [...new Set(cleaned)];
  }
  return config;
}
`;

export function buildClashVergeScript(items: ProxyDetail[]): ClashVergeExportResult {
  const publicProxies: ClashProxy[] = [];
  const personalProxies: ClashProxy[] = [];
  let skippedCount = 0;
  const names = new Set<string>();
  for (const item of items) {
    // local proxies stay in center storage only and are never exported to Clash Verge scripts.
    if (resolveProxyPrivacy(item) === 'local') {
      skippedCount += 1;
      continue;
    }
    const proxy = proxyDetailToClash(item);
    if (!proxy) { skippedCount += 1; continue; }
    let name = proxy.name;
    if (names.has(name)) name = `${name}_${item.id}`;
    names.add(name);
    const normalized = { ...proxy, name };
    if (resolveProxyPrivacy(item) === 'public') publicProxies.push(normalized);
    else personalProxies.push(normalized);
  }
  return { code: scriptTemplate(publicProxies, personalProxies), publicCount: publicProxies.length, personalCount: personalProxies.length, skippedCount };
}
